-- Dutch for story/story_*.lua; a missing key shows the English.

local T = {}

T["You find yourself walking through the quaint Fox Village in the forest."] = "Je wandelt door het schilderachtige Vossendorp in het bos."
T["It's a cloudy day, painting the town in a tone of gray."] = "Het is een bewolkte dag, die het dorp in grijze tinten hult."
T["Suddenly, you hear footsteps coming your way, and an impact against you blows you to the ground!"] = "Plotseling hoor je voetstappen jouw kant op komen -- en een harde botsing werpt je tegen de grond!"
T["You open your eyes back up, and find a familiar looking young fox boy crying."] = "Je doet je ogen weer open. Voor je zit een huilend vossenjongetje dat je ergens bekend voorkomt."
T["Are you okay? What's wrong?"] = "Gaat het? Wat is er aan de hand?"
T["Ow..."] = "Au …"
T["HEY! I'M WALKING HERE!"] = "HÉ! KIJK UIT JE DOPPEN!"
T["Ah, I'm so sorry! I..."] = "Ah, het spijt me zo! Ik …"
T["The boy pauses for a second, looking at you carefully."] = "De jongen houdt even stil en bekijkt je aandachtig."
T["You... {pause:0.4}\nYou're the one that's been visiting our dojo lately..."] = "Jij … {pause:0.4}\nJij bent degene die de laatste tijd vaak naar onze dojo komt …"
T["Ume?"] = "Ume?"
T["You're... Tsutaki! Right?"] = "Jij bent … Tsutaki! Toch?"
T["Who's this brat"] = "Wie is dat snotjong"
T["Phew... I'm glad to run into someone I already know..."] = "Oef … Gelukkig kom ik iemand tegen die ik al ken …"
T["The boy makes a disappointed expression."] = "De jongen kijkt teleurgesteld."
T["I... {pause:0.4}\nI suppose I never introduced myself properly."] = "Ik … {pause:0.4}\nIk heb me eigenlijk nooit echt voorgesteld, hè."
T["I'm Ume... {pause:0.4}\nI've seen you at our dojo, playing taiko drums before..."] = "Ik ben Ume … {pause:0.4}\nIk heb je weleens taiko zien spelen in onze dojo …"
T["Good to see you, but what's the matter?"] = "Leuk je te zien, maar wat is er?"
T["How come?"] = "Hoezo?"
T["That's a weird way to say \"nice to see you.\""] = "Rare manier om “leuk je te zien” te zeggen."
T["{shake:14,0.35}{sfx:shock}I'm sorry... {pause:0.4}\nI don't mean to be rude... {pause:0.4}\nBut..."] = "{shake:14,0.35}{sfx:shock}Sorry … {pause:0.4}\nIk wil niet onbeleefd zijn … {pause:0.4}\nMaar …"
T["Ume seems pretty scared, so you pause to listen to what he has to say."] = "Ume lijkt behoorlijk bang, dus je houdt even stil om te horen wat hij te zeggen heeft."
T["Well, you see... {pause:0.4}\nThere's this quiet pagoda holding our ancestors relics deep in the woods and... {pause:0.4}\nRecently, the aura around it turned all... weird, and stuff."] = "Nou, kijk … {pause:0.4}\nDiep in het bos staat een stille pagode met de relikwieën van onze voorouders, en … {pause:0.4}\nSinds kort is de aura eromheen helemaal … raar geworden en zo."
T["It's normally empty and serene, but it started to have a strange dark energy enveloping it, more and more with each day I visit."] = "Normaal is het daar leeg en vredig, maar nu hangt er een vreemde, duistere energie omheen -- en elke dag dat ik ga kijken, wordt het erger."
T["The stream around it has become as big as a lake, growing just like the weird darky stuff..."] = "Het beekje eromheen is zo groot als een meer geworden, en het groeit net zo hard als dat rare donkere gedoe …"
T["And... when I stepped inside, even just one step... {pause:0.4}\nsome... {pause:0.4}{expr:fear2}some creature tried to attack me! {pause:0.4}\nIt was scary... I'm scared...!!"] = "En … toen ik naar binnen stapte, maar één stapje … {pause:0.4}\nprobeerde een … {pause:0.4}{expr:fear2}een of ander wezen me aan te vallen! {pause:0.4}\nHet was zo eng … Ik ben bang …!!"
T["Have you asked one of your grown-ups about it?"] = "Heb je het al aan een volwassene gevraagd?"
T["That's called a squirrel. It's just a squirrel."] = "Dat is een eekhoorn. Gewoon een eekhoorn."
T["Well... Tsubaki thinks I'm lying, or that it's not important. {pause:0.4}\nShe says it's so deep in the woods that it wouldn't matter, but it's CLEARLY dangerous! {pause:0.4}\nSUPER DUPER dangerous!"] = "Nou … Tsubaki denkt dat ik lieg, of dat het niet belangrijk is. {pause:0.4}\nZe zegt dat het zo diep in het bos is dat het niet uitmaakt, maar het is OVERDUIDELIJK gevaarlijk! {pause:0.4}\nSUPER-DE-DUPER gevaarlijk!"
T["Asagao didn't say anything or do anything about it, so maybe they think I'm making it up too, but..."] = "Asagao heeft er niks over gezegd en er ook niks aan gedaan, dus misschien denkt die ook dat ik het verzin, maar …"
T["I feel like if we don't do something soon, our village could be in some really bad danger..."] = "Ik heb het gevoel dat als we niet snel iets doen, ons dorp in heel groot gevaar kan komen …"
T["... Do you think you could help me, maybe? {pause:0.4}\nYou're the only other super strong person I can think of..."] = "… Denk je dat je me misschien kunt helpen? {pause:0.4}\nJij bent de enige andere supersterke persoon die ik ken …"
T["Of course, Ume. Take me there."] = "Natuurlijk, Ume. Breng me erheen."
T["Ume looks down, with an upset expression. {pause:0.4}\nHe took that in a not-great way."] = "Ume kijkt naar de grond, duidelijk gekwetst. {pause:0.4}\nDat viel niet zo goed."
T["{shake:14,0.35}{sfx:shock}It... {pause:0.4}It wasn't a squirrel... {pause:0.4}I promise..."] = "{shake:14,0.35}{sfx:shock}Het … {pause:0.4}Het was geen eekhoorn … {pause:0.4}Echt waar …"
T["I really need your help... {pause:0.4}\nNo one else believes me either, but it really could put the village in some bad danger..."] = "Ik heb je hulp echt nodig … {pause:0.4}\nNiemand anders gelooft me ook, maar het kan het dorp echt in groot gevaar brengen …"
T["Can I at least show you the scary thing...? {pause:0.4}\nYou're really my last hope..."] = "Mag ik je dat enge ding dan tenminste laten zien …? {pause:0.4}\nJij bent echt mijn laatste hoop …"
T["I'm sorry, I didn't mean to hurt your feelings. Show me, I'll help."] = "Sorry, ik wilde je niet kwetsen. Laat maar zien, ik help je."
T["... Uh, okay..."] = "… Eh, oké …"
T["The squirrel? Yeah, I guess."] = "De eekhoorn? Ja, vooruit dan."
T["No."] = "Nee."
T["It's not a squirrel!!"] = "Het is geen eekhoorn!!"
T["The two of you reach the forest from the dojo backdoor, and are ready for a long journey."] = "Samen gaan jullie via de achterdeur van de dojo het bos in, klaar voor een lange tocht."
T["The two of you run through the forest, and reach the entrance gate to the sacred place.\nA long climb waits before reaching the deserted pagoda."] = "Samen rennen jullie door het bos en bereiken jullie de toegangspoort van de heilige plek.\nEr wacht een lange klim voordat jullie bij de verlaten pagode zijn."
T["The two of you run through the forest, and reach the deserted pagoda, which was indeed distorted with purple hues.\nYou feel like something bad is brewing inside."] = "Samen rennen jullie door het bos en bereiken jullie de verlaten pagode, die inderdaad vervormd is door paarse tinten.\nJe voelt dat er binnen iets kwaads broeit."
T["The two of you enter the pagoda."] = "Samen gaan jullie de pagode binnen."
T["Wait! Pleas-"] = "Wacht! Alsjebl--"
T["You leave the fox village, leaving it to its terrible fate...\nYou're hungry, stopping by the local convenience store before going back home."] = "Je verlaat het Vossendorp en laat het aan zijn verschrikkelijke lot over …\nJe hebt honger en wipt nog even binnen bij de buurtsuper voordat je naar huis gaat."
T["Hey Boss! {pause:0.4}\nAre you ready to take on the pagoda again?"] = "Hé, baas! {pause:0.4}\nBen je klaar om het weer tegen de pagode op te nemen?"
T["Sure am!"] = "Zeker weten!"
T["Boss???"] = "Baas???"
T["Pago... Pagowhat?"] = "Pago … Pagowat?"
T["I literally don't want to, tiny coward"] = "Echt geen zin in, kleine schijterd"
T["Thank you! {pause:0.4}\nI'm happy to hear that!"] = "Dankjewel! {pause:0.4}\nDat is fijn om te horen!"
T["You're the bigger, stronger person! {pause:0.4}\nThat's what a boss is, right? {pause:0.4}\n...Right?"] = "Jij bent groter en sterker dan ik! {pause:0.4}\nDat is toch wat een baas is? {pause:0.4}\n… Toch?"
T["I suppose so."] = "Ik denk het wel."
T["I'm not sure that's how it works..."] = "Ik weet niet of het zo werkt …"
T["Yes, my minion."] = "Ja, mijn handlanger."
T["Minion...?? {pause:0.4}\n... *Ahem.*"] = "Handlanger …?? {pause:0.4}\n… *Ahum.*"
T["Ume blinks at you, concerned."] = "Ume knippert bezorgd met zijn ogen."
T["Uh... {pause:0.4}Y'know... {pause:0.4}\nthe... {pause:0.4}the thing... {pause:0.4}\nthe thing we did..."] = "Eh … {pause:0.4}Je weet wel … {pause:0.4}\ndat … {pause:0.4}dat ding … {pause:0.4}\ndat ding dat we samen gedaan hebben …"
T["... {pause:0.4}\nUgh... {pause:0.4}\nokay..."] = "… {pause:0.4}\nPff … {pause:0.4}\noké …"
T["Ume sighs, and explains it all to you again."] = "Ume zucht en legt je alles nog een keer uit."
T["You start walking away from Ume."] = "Je draait je om en loopt bij Ume weg."
T["{shake:14,0.35}{sfx:shock}NOO WAIT!! {pause:0.4}WAAIT!!!"] = "{shake:14,0.35}{sfx:shock}NEEE, WACHT!! {pause:0.4}WAACHT!!!"
T["Ume drags you back, before trying to convince you to help."] = "Ume sleurt je terug en probeert je over te halen om te helpen."
T["Remember, any progress is good progress. {pause:0.4}\nAs long as we get in there and give them even a smidge of a scare, I think the village would be safe, but..."] = "Onthoud: elke stap vooruit is er een. {pause:0.4}\nAls we daar naar binnen gaan en ze ook maar een klein beetje laten schrikken, is het dorp volgens mij veilig, maar …"
T["I don't want the pagoda to stay like this forever... {pause:0.4}\nI'm sure, someday, we'll make it to the very top and restore it!"] = "Ik wil niet dat de pagode voor altijd zo blijft … {pause:0.4}\nIk weet zeker dat we ooit helemaal bovenaan komen en de pagode weer in ere herstellen!"
T["That's the spirit, Ume!"] = "Zo mag ik het horen, Ume!"
T["That's optimistic."] = "Dat is optimistisch."
T["I don't want to play with you anymore."] = "Ik wil niet meer met je spelen."
T["...bye HAHAHAAHAAAHA"] = "… doei HAHAHAAHAAAHA"
T["You leave the fox village, leaving it to its terrible fate..."] = "Je verlaat het Vossendorp en laat het aan zijn verschrikkelijke lot over …"
T["You're hungry, stopping by the local convenience store before going back home."] = "Je hebt honger en wipt nog even binnen bij de buurtsuper voordat je naar huis gaat."
T["The two of you enter the forest behind the dojo."] = "Samen gaan jullie het bos achter de dojo in."
T["The two of you reach the stairs leading to the pagoda."] = "Samen bereiken jullie de trap naar de pagode."
T["The once-deserted pagoda, now reaching to the edge of the sky shines in the middle of the forest, glowing in sunlight."] = "De ooit verlaten pagode, die nu tot aan de rand van de hemel reikt, straalt midden in het bos in het zonlicht."
T["Heeeey, Boss!!!!!"] = "Heeeee, baas!!!!!"
T["Ume is energetically running towards you."] = "Ume komt vol energie op je af gerend."
T["I'm so happy to run into you here!"] = "Ik ben zo blij dat ik je hier tegenkom!"
T["I am too!"] = "Ik ook!"
T["Ok bud."] = "Ja ja, kereltje."
T["The two of you stand there, taking in the scenery of nature."] = "Samen staan jullie te genieten van de natuur om jullie heen."
T["The two of you stand there, taking in the scenery of nature. {pause:0.4}\nHe didn't understand that you were trying to dismiss him."] = "Samen staan jullie te genieten van de natuur om jullie heen. {pause:0.4}\nHij snapte niet dat je hem probeerde af te poeieren."
T["It's still so strange isn't it? {pause:0.4}\nI wonder why Tobiraph did everything that it did."] = "Het is nog steeds zo raar, hè? {pause:0.4}\nIk vraag me af waarom Tobiraph dat allemaal heeft gedaan."
T["I've been thinking about it too. I sorta want to know more."] = "Daar dacht ik ook al aan. Ik wil er meer over weten."
T["..."] = "…"
T["Hey, why don't we play pretend that it's still.. weird? {pause:0.4}\nI had so much fun with you, and I kind of wish we could do it again."] = "Hé, zullen we doen alsof het nog steeds … raar is? {pause:0.4}\nIk vond het zo leuk met jou, en eigenlijk zou ik het best nog een keer willen doen."
T["I'd be happy to!"] = "Heel graag!"
T["That's why I'm here."] = "Daarom ben ik hier."
T["You nod."] = "Je knikt."
T["Maybe another time."] = "Een andere keer misschien."
T["Understood! Don't hesitate to come anytime..."] = "Begrepen! Kom gerust langs wanneer je maar wilt …"
T["You leave the fox village...\nWhy did you came here already?"] = "Je verlaat het Vossendorp …\nWaarom was je hier ook alweer gekomen?"
T["The two of you enter the forest behind the dojo, with eyes filled with imagination."] = "Samen gaan jullie het bos achter de dojo in, met ogen vol fantasie."
T["The two of you reach the stairs leading to the pagoda, with eyes filled with imagination."] = "Samen bereiken jullie de trap naar de pagode, met ogen vol fantasie."
T["The two of you enter the pagoda, with eyes filled with imagination."] = "Samen gaan jullie de pagode binnen, met ogen vol fantasie."
T["... {pause:0.4}\nThat look on your face is telling me that you want to climb higher."] = "… {pause:0.4}\nAan je gezicht te zien wil je nog hoger klimmen."
T["I am!"] = "Klopt!"
T["I just wanna check it out."] = "Ik wil gewoon even kijken."
T["Neva neva neva!"] = "Nooit, nooit, nooit niet!"
T["Then I'll go up to the roof with you, too!"] = "Dan ga ik ook met je mee naar het dak!"
T["... {pause:0.4}\nThough I probably won't climb that thing, there's some stuff I need to check on inside the pagoda."] = "… {pause:0.4}\nIk ga dat ding waarschijnlijk niet beklimmen, hoor. Ik moet in de pagode nog wat dingen nakijken."
T["I'll cheer you on the best I can, though!"] = "Maar ik zal je zo goed mogelijk aanmoedigen!"
T["You start climbing the beanstalk, without knowing what to expect..."] = "Je begint aan de bonenstaak omhoog te klimmen, zonder te weten wat je te wachten staat …"

return T
